def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    failure = [0] * len(transitions)
    queue = []

    for c in range(size):
        state = transitions[0][c]
        if state == -1:
            transitions[0][c] = 0
        else:
            queue.append(state)

    for state in queue:
        terminal[state] |= terminal[failure[state]]
        for c in range(size):
            nxt = transitions[state][c]
            if nxt == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[nxt] = transitions[failure[state]][c]
                queue.append(nxt)

    safe_states = [state for state in range(len(transitions)) if not terminal[state]]
    compact = {state: i for i, state in enumerate(safe_states)}
    m = len(safe_states)

    matrix = [[0] * m for _ in range(m)]
    for state in safe_states:
        row = matrix[compact[state]]
        for nxt in transitions[state]:
            if not terminal[nxt]:
                row[compact[nxt]] += 1

    vector = [0] * m
    vector[compact[0]] = 1

    def multiply_vector(vec, mat):
        result = [0] * m
        for i, value in enumerate(vec):
            if value:
                for j, entry in enumerate(mat[i]):
                    result[j] = (result[j] + value * entry) % MOD
        return result

    def square(mat):
        result = [[0] * m for _ in range(m)]
        for i in range(m):
            for k, value in enumerate(mat[i]):
                if value:
                    for j, entry in enumerate(mat[k]):
                        result[i][j] = (result[i][j] + value * entry) % MOD
        return result

    while n:
        if n & 1:
            vector = multiply_vector(vector, matrix)
        n >>= 1
        if n:
            matrix = square(matrix)

    return sum(vector) % MOD
